#!/usr/bin/env python3
import json
import os
import requests

def read_env_file(file_path):
    """Read environment variables from a .env file"""
    env_vars = {}

    with open(file_path, 'r') as f:
        for line in f:
            line = line.strip()
            # Skip empty lines and comments
            if line and not line.startswith('#'):
                if '=' in line:
                    key, value = line.split('=', 1)
                    env_vars[key] = value

    return env_vars

def main():
    # Read environment variables
    env_vars = read_env_file('.env.test')

    # Convert to JSON
    json_payload = json.dumps(env_vars, indent=2)

    print("Environment variables to export:")
    print(json_payload)

    # POST to documentation wiki
    url = "http://localhost:3003/api/doc-export"
    headers = {
        'Content-Type': 'application/json',
        'User-Agent': 'env-exporter-script'
    }

    try:
        response = requests.post(url, json=env_vars, headers=headers)
        response.raise_for_status()
        print(f"\n✓ Successfully exported to {url}")
        print(f"Response status: {response.status_code}")

        if response.text:
            print(f"Response: {response.text}")

    except requests.exceptions.RequestException as e:
        print(f"\n✗ Error exporting to {url}: {e}")
        return 1

    return 0

if __name__ == "__main__":
    exit(main())

